function text(prop) { return prop?.rich_text?.map(x => x.plain_text ?? x.text?.content ?? '').join('') ?? ''; }
function title(prop) { return prop?.title?.map(x => x.plain_text ?? x.text?.content ?? '').join('') ?? ''; }
function number(prop) { return prop?.number ?? 0; }
function checkbox(prop) { return !!prop?.checkbox; }
function dateStart(prop) { return prop?.date?.start ?? null; }
const monthNames = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
