    'Réservation liée': { relation: [{ id: page.id }] },
    'Statut': { select: { name: 'À planifier' } },
    'Priorité': { select: { name: 'Normale' } },
    'Type intervention': { select: { name: 'Rotation complète' } },
    'Source création': { select: { name: 'n8n' } },
    'Validation réservation': { checkbox: true },
    'Paiement intervenant': { select: { name: 'À payer' } },
    'Nb voyageurs': { number: number(p['Voyageurs']) },
    'Nb nuits': { number: number(p['Nb nuits']) },
    'Lit chambre à préparer': { checkbox: checkbox(p['Lit chambre requis']) },
    'Canapé-lit à préparer': { checkbox: checkbox(p['Canapé-lit requis']) },
    'Jeux chambre à prendre': { number: number(p['Jeux chambre requis']) },
    'Jeux canapé à prendre': { number: number(p['Jeux canapé requis']) },
    'Serviettes à prendre': { number: number(p['Serviettes']) },
    'Taies à prendre': { number: number(p['Taies requises']) },
    'Tapis bain à prendre': { number: number(p['Tapis bain requis']) },
    'Torchons à prendre': { number: number(p['Torchons requis']) },
    'Bouteilles eau à installer': { number: number(p['Bouteilles eau requises']) },
    'Capsules T-disc à installer': { number: number(p['Capsules T-disc requises']) },
    'Rouleaux WC à installer': { number: number(p['Rouleaux WC prévus']) },
    'Sacs cuisine à prévoir': { number: number(p['Sacs cuisine prévus']) },
    'Sacs WC à prévoir': { number: number(p['Sacs WC prévus']) },
    'Demandes particulières': { rich_text: specialInstructions ? [{ text: { content: specialInstructions } }] : [] },
    'Arrivée voyageur validée': { rich_text: text(p['Heure arrivée validée']) ? [{ text: { content: text(p['Heure arrivée validée']) } }] : [] },
    'Contrainte horaire': { rich_text: text(p['Contrainte arrivée']) ? [{ text: { content: text(p['Contrainte arrivée']) } }] : [] },
    'Passage cave requis': { checkbox: number(p['Jeux chambre requis']) > 0 || number(p['Jeux canapé requis']) > 0 || number(p['Serviettes']) > 0 },
    'Incident constaté': { checkbox: false },
    'Photos finales reçues': { checkbox: false },
    'Contrôle final validé': { checkbox: false },
    'Steve prévenu': { checkbox: false },
    'Date dernière mise à jour': { date: { start: new Date().toISOString() } },
    'ID automatisation': { rich_text: [{ text: { content: `reservation:${reservationId}` } }] }
  };
  if (arrival) interventionProperties['Date intervention'] = { date: { start: arrival } };
  return { json: { reservation_page_id: page.id, reservation_id_compact: reservationId, reservation_title: title(p['Réservation']), intervention_properties: interventionProperties }, pairedItem: { item: 0 } };
});

